// Validate the token: must exist, not be expired, not be consumed.
const token = $('Webhook').first().json.query.token;
const rows = items.map(i => i.json).filter(r => r && r.token);
const row = rows.find(r => r.token === token) || null;

let valid = false;
let reason = 'not_found';

if (row) {
  const consumed = row.consumed === true || row.consumed === 'true';
  const expired = row.expiresAt ? new Date(row.expiresAt).getTime() < Date.now() : false;
  if (consumed) reason = 'already_consumed';
  else if (expired) reason = 'expired';
  else { valid = true; reason = 'ok'; }
}

return [{ json: { ...(row || {}), token, valid, reason, locale: (row && row.locale) || 'nl' } }];

// Fills the published Webflow report template with the five validated JSON sections and
// the profile, and hands PDFShift a self-contained page. The template is the design
// surface Alex edits; every dynamic value is an element carrying a data-slot attribute.
// A template that lost a slot throws — placeholder copy must never reach a reader.
const p = $('Validate Token').first().json;
const r = $json.report;
const SECTIONS = ['opening', 'reaction', 'origin', 'cost', 'closing'];
const TEMPLATE_URL = 'https://nem-life-1.webflow.io/report-pdf-template';
const FONTS_CSS = 'https://cdn.jsdelivr.net/gh/studiozissou/webflow-scripts@11d3a83cccce1190e1c1195184e0ca312bae9b33/projects/nem-life/src/report-fonts.css';

const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

let html = String(await this.helpers.httpRequest({ method: 'GET', url: TEMPLATE_URL, json: false }));

const missing = (what) => new Error('Report template is missing ' + what + ' - check ' + TEMPLATE_URL);

// The whole element carrying the attribute: tag, attributes before, attributes after, inner html.
const elementRe = (attr, name) => new RegExp(
  '<(\\w+)\\b([^>]*?)\\s*' + attr + '="' + name + '"([^>]*)>([\\s\\S]*?)</\\1>'
);

// Replaces the inner html of a text slot, keeping the element and its attributes.
const fillText = (name, value) => {
  const re = elementRe('data-slot', name);
  if (!re.test(html)) throw missing('data-slot="' + name + '"');
  html = html.replace(re, (m, tag, before, after) =>
    '<' + tag + before + ' data-slot="' + name + '"' + after + '>' + value + '</' + tag + '>');
};

// A section placeholder is one paragraph; the prose becomes one paragraph per blank line,
// each carrying the placeholder's class so the Designer's paragraph styling applies.
const fillSection = (name, text) => {
  const re = elementRe('data-slot', name);
  const m = html.match(re);
  if (!m) throw missing('data-slot="' + name + '"');
  const cls = (m[2] + ' ' + m[3]).match(/class="([^"]*)"/);
  const open = '<p' + (cls ? ' class="' + cls[1] + '"' : '') + '>';
  const paras = esc(text).trim().split(/\n{2,}/)
    .map((x) => open + x.replace(/\n/g, '<br>') + '</p>')
    .join('');
  html = html.replace(re, () => '<div data-slot="' + name + '">' + paras + '</div>');
};

// Fixed editorial copy, selected client-side on the conclusion key alone. Empty until
// Alex's Intro lines tab is exported — then the whole block goes, not just the text.
const introLine = String(p.introLine || '').trim();
if (introLine) {
  fillText('intro-line', esc(introLine));
} else {
  if (!elementRe('data-slot', 'intro-line').test(html)) throw missing('data-slot="intro-line"');
  const wrapRe = new RegExp(elementRe('data-slot-wrap', 'intro-line').source, 'g');
  if (!wrapRe.test(html)) throw missing('data-slot-wrap="intro-line"');
  wrapRe.lastIndex = 0;
  html = html.replace(wrapRe, '');
}

const date = new Intl.DateTimeFormat('nl-NL', {
  day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Amsterdam',
}).format(new Date());

fillText('first-name', esc(p.firstName || ''));
fillText('date', date);
SECTIONS.forEach((k) => fillSection(k, r[k]));

// PDF-safe: no scripts (the WebFont loader, jQuery, init.js), no lazy images (PDFShift does
// not scroll), the brand fonts embedded through a render-blocking stylesheet, print rules.
html = html
  .replace(/<script\b[\s\S]*?<\/script>/gi, '')
  .replace(/\sloading="lazy"/g, '');

const printCss = '<link rel="stylesheet" href="' + FONTS_CSS + '">'
  + '<style>'
  + '@page{size:A4;margin:12mm 0 14mm}'
  + '@page:first{margin-top:0}'
  + '*{-webkit-print-color-adjust:exact;print-color-adjust:exact}'
  + '.report_block.is-final,.report_block.is-disclaimer,.block-conclusion{break-inside:avoid}'
  + 'h2,h2 + div{break-after:avoid}'
  + 'p{orphans:3;widows:3}'
  + 'div[data-slot] > p + p{margin-top:1rem}'
  + '</style>';
if (!html.includes('</head>')) throw missing('a <head>');
html = html.replace('</head>', () => printCss + '</head>');

const reportText = SECTIONS.map((k) => r[k]).join('\n\n');

return [{ json: Object.assign({ html: html, reportText: reportText }, p) }];

// Base64-encode the PDFShift binary so MailerSend can attach it.
const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({ json: { ...items[i].json, pdfBase64: buf.toString('base64') } });
}
return out;

// Validates the report JSON contract. Mirror of projects/nem-life/src/nem-report-parse.js,
// which is unit-tested in tests/nem/nem-report-parse.test.js - keep the two in step.
// This is a gate on the live report path: anything rejected here means the user gets
// nothing, so it is strict about shape and tolerant about presentation.
const REPORT_KEYS = ['opening', 'reaction', 'origin', 'cost', 'closing'];
const RAW_LIMIT = 2000;

function extractText(response) {
  const blocks = response && response.content;
  if (!Array.isArray(blocks)) return null;
  const text = blocks
    .filter(b => b && b.type === 'text' && typeof b.text === 'string')
    .map(b => b.text)
    .join('');
  return text.length > 0 ? text : null;
}

function unwrap(text) {
  const trimmed = text.trim();
  const fenced = /^```[a-zA-Z]*\s*\n?([\s\S]*?)\n?```$/.exec(trimmed);
  return (fenced ? fenced[1] : trimmed).trim();
}

function isPlainObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function fail(reason, detail, raw) {
  return {
    valid: false,
    reason: reason,
    detail: detail,
    raw: String(raw == null ? '' : raw).slice(0, RAW_LIMIT)
  };
}

function parseReport(response) {
  const text = extractText(response);
  // Checked before parsing: truncated JSON fails to parse anyway, but "unexpected end of
  // input" tells nobody what to change, whereas this points straight at max_tokens.
  if (response && response.stop_reason === 'max_tokens') {
    return fail('truncated', 'Anthropic stopped at max_tokens - the report was cut short. Raise max_tokens or shorten the prompt.', text);
  }
  if (text === null) return fail('not-json', 'No text block in the model response.', '');
  let parsed;
  try {
    parsed = JSON.parse(unwrap(text));
  } catch (e) {
    return fail('not-json', 'Response is not valid JSON: ' + e.message, text);
  }
  if (!isPlainObject(parsed)) {
    return fail('not-json', 'Parsed to ' + (Array.isArray(parsed) ? 'an array' : typeof parsed) + ', expected an object.', text);
  }
  const missing = REPORT_KEYS.filter(k => !(k in parsed));
  if (missing.length > 0) return fail('missing-key', 'Missing: ' + missing.join(', ') + '.', text);
  const empty = REPORT_KEYS.filter(k => typeof parsed[k] !== 'string' || parsed[k].trim().length === 0);
  if (empty.length > 0) return fail('empty-value', 'Empty or non-string: ' + empty.join(', ') + '.', text);
  const report = {};
  for (const k of REPORT_KEYS) report[k] = parsed[k];
  return { valid: true, report: report };
}

const result = parseReport($json);
const p = $('Validate Token').first().json;

return [{
  json: Object.assign({}, p, {
    parseValid: result.valid,
    report: result.valid ? result.report : null,
    reason: result.valid ? '' : result.reason,
    detail: result.valid ? '' : result.detail,
    rawResponse: result.valid ? '' : result.raw,
    executionId: String($execution.id),
    failedAt: new Date().toISOString()
  })
}];

// The report prompt is Dutch-only, so any other locale is logged and alerted instead of
// calling Anthropic. Emits the exact shape Parse Report emits on failure, so Log Failure
// and Alert Failure need no changes.
const p = $('Validate Token').first().json;

return [{
  json: Object.assign({}, p, {
    parseValid: false,
    report: null,
    reason: 'unsupported-locale',
    detail: 'Locale "' + p.locale + '" has no report prompt - only nl is supported. No model call was made.',
    rawResponse: '',
    executionId: String($execution.id),
    failedAt: new Date().toISOString()
  })
}];
